<?php
require __DIR__.'/config/auth.php';requireLogin();require __DIR__.'/config/db.php';require __DIR__.'/config/layout.php';
$q=trim($_GET['q']??'');$rows=[];
if($q!==''){$like='%'.$q.'%';if(esAdmin()){$st=$pdo->prepare('SELECT d.*,s.nombre sector FROM documentos d JOIN sectores s ON s.id=d.sector_id WHERE d.titulo LIKE ? OR d.descripcion LIKE ? ORDER BY d.id DESC');$st->execute([$like,$like]);}else{$st=$pdo->prepare('SELECT d.*,s.nombre sector FROM documentos d JOIN usuario_sector us ON us.sector_id=d.sector_id JOIN sectores s ON s.id=d.sector_id WHERE us.usuario_id=? AND (d.titulo LIKE ? OR d.descripcion LIKE ?) ORDER BY d.id DESC');$st->execute([$_SESSION['usuario_id'],$like,$like]);}$rows=$st->fetchAll();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><link rel="stylesheet" href="../style.css"></head><body><div class="app"><?php sidebar($pdo,'buscar');?><main class="content"><header class="section-top"><div><p class="eyebrow">BUSCADOR GLOBAL</p><h1>Buscar documentos</h1></div></header><form method="get" class="form-row" style="grid-template-columns:1fr auto"><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="Nombre, palabra clave..."><button class="btn primary">Buscar</button></form><section class="document-grid" style="margin-top:24px"><?php foreach($rows as $d):?><article class="document-card"><span class="type-badge"><?=htmlspecialchars($d['sector'])?></span><h3><?=htmlspecialchars($d['titulo'])?></h3><p><?=htmlspecialchars($d['descripcion']??'')?></p></article><?php endforeach;?></section></main></div></body></html>